import collections
import json
import re
import sqlite3

import psycopg2


SQLITE_PATH = "/workspace/query_dataset/patent_publication.db"
PG_KWARGS = {
    "host": "dab-postgres",
    "port": 5432,
    "dbname": "patent_CPCDefinition",
    "user": "postgres",
    "password": "postgres",
}

INFO_PATTERNS = [
    re.compile(r"^(?P<assignee>.+?) holds the [A-Z]{2} (?:patent )?(?:application|filing)\b", re.I),
    re.compile(
        r"^The [A-Z]{2} (?:patent )?(?:application|filing)\b.*? is "
        r"(?:assigned to|owned by|held by|belonging to) (?P<assignee>.+?) and has",
        re.I,
    ),
    re.compile(
        r"^(?:Patent (?:application|filing)|Application)\b.*? from [A-Z]{2}, "
        r"(?:owned by|held by|assigned to|belonging to) (?P<assignee>.+?), with",
        re.I,
    ),
    re.compile(
        r"^In [A-Z]{2}, the (?:patent )?(?:application|filing)\b.*? is "
        r"(?:owned by|assigned to|held by|belonging to) (?P<assignee>.+?) and has",
        re.I,
    ),
]
PUB_RE = re.compile(r"(?:publication number|publication no\.|pub\. number)\s+([A-Z]{2}-[^.]+?)(?:\.|$)", re.I)
APP_RE = re.compile(r"(?:application\s+(?:no\.|number)|app\. number|ID|no\.|number)\s+([A-Z]{2}-[A-Z0-9]+-[A-Z])", re.I)
YEAR_RE = re.compile(r"\b((?:19|20)\d{2})\b")
MONTHS = {
    name: idx
    for idx, names in enumerate(
        [
            ["jan", "january"],
            ["feb", "february"],
            ["mar", "march"],
            ["apr", "april"],
            ["may"],
            ["jun", "june"],
            ["jul", "july"],
            ["aug", "august"],
            ["sep", "sept", "september"],
            ["oct", "october"],
            ["nov", "november"],
            ["dec", "december"],
        ],
        1,
    )
    for name in names
}
MONTH_RE = re.compile(r"\b(" + "|".join(sorted(MONTHS, key=len, reverse=True)) + r")\b", re.I)


def parse_info(text):
    assignee = None
    for pattern in INFO_PATTERNS:
        match = pattern.search(text or "")
        if match:
            assignee = match.group("assignee").strip()
            break
    pub_match = PUB_RE.search(text or "")
    app_match = APP_RE.search(text or "")
    pub = pub_match.group(1).strip() if pub_match else None
    app = app_match.group(1).strip() if app_match else None
    country = pub.split("-", 1)[0] if pub else None
    return assignee, pub, app, country


def year_month(text):
    year_match = YEAR_RE.search(text or "")
    month_match = MONTH_RE.search(text or "")
    year = int(year_match.group(1)) if year_match else None
    month = MONTHS[month_match.group(1).lower()] if month_match else None
    return year, month


def load_cpc_definitions():
    conn = psycopg2.connect(**PG_KWARGS)
    cur = conn.cursor()
    cur.execute('select symbol, level::int, "titleFull", parents from cpc_definition')
    symbols = {}
    level_symbols = collections.defaultdict(set)
    titles = {}
    for symbol, level, title, parents_text in cur.fetchall():
        try:
            parents = json.loads(parents_text) if parents_text else []
        except Exception:
            parents = []
        symbols[symbol] = (level, title, parents)
        level_symbols[level].add(symbol)
        titles[symbol] = title
    conn.close()
    return symbols, level_symbols, titles


def make_mapper(symbols, level_symbols):
    cache = {}
    methods = collections.Counter()

    def fallback_prefix(code, target_level):
        prefix = code[:3] if target_level == 4 else code[:4]
        return prefix if prefix in level_symbols[target_level] else None

    def ancestor_at_level(code, target_level):
        key = (code, target_level)
        if key in cache:
            return cache[key]
        group = None
        method = "none"
        record = symbols.get(code)
        if record:
            level, _title, parents = record
            if level == target_level:
                group = code
                method = "exact"
            else:
                for parent in parents:
                    if parent in symbols and symbols[parent][0] == target_level:
                        group = parent
                        method = "parent"
                        break
        if group is None:
            group = fallback_prefix(code, target_level)
            if group:
                method = "prefix"
        cache[key] = group
        methods[method] += 1
        return group

    return ancestor_at_level, cache, methods


def primary_groups(cpc_entries, target_level, ancestor_at_level):
    groups = set()
    for entry in cpc_entries:
        if isinstance(entry, dict) and entry.get("first") is True and entry.get("code"):
            group = ancestor_at_level(entry["code"], target_level)
            if group:
                groups.add(group)
    return groups


def best_years(counts, alpha):
    result = {}
    details = {}
    for group, by_year in counts.items():
        ema = None
        max_ema = None
        best = None
        seq = []
        for year in range(min(by_year), max(by_year) + 1):
            count = by_year.get(year, 0)
            ema = count if ema is None else alpha * count + (1 - alpha) * ema
            seq.append((year, count, ema))
            if max_ema is None or ema > max_ema + 1e-12:
                max_ema = ema
                best = year
        result[group] = best
        details[group] = {"best_year": best, "max_ema": max_ema, "seq": seq}
    return result, details


def main():
    symbols, level_symbols, titles = load_cpc_definitions()
    ancestor_at_level, map_cache, map_methods = make_mapper(symbols, level_symbols)

    counts_q1 = collections.defaultdict(collections.Counter)
    counts_q2 = collections.defaultdict(collections.Counter)
    by_pub = {}
    uc_pubs = set()
    coverage = collections.Counter()
    failures = collections.defaultdict(list)
    primary_unique = set()
    unique_codes = set()
    profile = {
        "cpc_definition_rows": len(symbols),
        "level4_symbols": len(level_symbols[4]),
        "level5_symbols": len(level_symbols[5]),
        "publication_rows": 0,
        "cpc_entries": 0,
        "citation_entries": 0,
        "q1": {"input": 0, "parsed": 0, "joined": 0, "memberships": 0},
        "q2": {"input": 0, "parsed": 0, "joined": 0, "memberships": 0},
    }

    conn = sqlite3.connect(SQLITE_PATH)
    conn.row_factory = sqlite3.Row
    for row in conn.execute("select rowid, Patents_info, filing_date, grant_date, cpc from publicationinfo"):
        profile["publication_rows"] += 1
        profile["q1"]["input"] += 1
        assignee, pub, app, country = parse_info(row["Patents_info"])
        filing_year, _filing_month = year_month(row["filing_date"])
        grant_year, grant_month = year_month(row["grant_date"])

        for key, value in [
            ("assignee", assignee),
            ("publication_number", pub),
            ("application_number", app),
            ("country", country),
            ("filing_year", filing_year),
            ("grant_year", grant_year),
            ("grant_month", grant_month),
        ]:
            if value:
                coverage[key] += 1
            elif len(failures[key]) < 5:
                failures[key].append(row[key] if key in row.keys() else row["Patents_info"])

        try:
            cpc_entries = json.loads(row["cpc"] or "[]")
            coverage["cpc_json"] += 1
        except Exception as exc:
            cpc_entries = []
            if len(failures["cpc_json"]) < 5:
                failures["cpc_json"].append({"rowid": row["rowid"], "error": str(exc)})

        for entry in cpc_entries:
            if isinstance(entry, dict) and entry.get("code"):
                unique_codes.add(entry["code"])
                profile["cpc_entries"] += 1
                if entry.get("first") is True:
                    primary_unique.add(entry["code"])

        level5 = primary_groups(cpc_entries, 5, ancestor_at_level)
        if pub:
            by_pub[pub] = {"assignee": assignee, "level5": level5}
            if assignee == "UNIV CALIFORNIA":
                uc_pubs.add(pub)

        if filing_year:
            profile["q1"]["parsed"] += 1
            if level5:
                profile["q1"]["joined"] += 1
                profile["q1"]["memberships"] += len(level5)
            for group in level5:
                counts_q1[group][filing_year] += 1

        if country == "DE" and grant_year == 2019 and grant_month and grant_month >= 7:
            profile["q2"]["input"] += 1
            if filing_year:
                profile["q2"]["parsed"] += 1
                level4 = primary_groups(cpc_entries, 4, ancestor_at_level)
                if level4:
                    profile["q2"]["joined"] += 1
                    profile["q2"]["memberships"] += len(level4)
                for group in level4:
                    counts_q2[group][filing_year] += 1
    conn.close()

    # Prime mapper coverage for all unique primary codes at relevant levels.
    for code in primary_unique:
        ancestor_at_level(code, 4)
        ancestor_at_level(code, 5)

    best_q1, details_q1 = best_years(counts_q1, 0.2)
    q1_codes = sorted(group for group, best in best_q1.items() if best == 2022)
    best_q2, details_q2 = best_years(counts_q2, 0.1)
    q2_rows = sorted(
        {
            "title": titles[group],
            "code": group,
            "best_year": best_q2[group],
            "max_ema": details_q2[group]["max_ema"],
            "total_filings": sum(counts_q2[group].values()),
        }
        for group in counts_q2
    )

    california_variants = collections.Counter()
    for meta in by_pub.values():
        assignee = meta["assignee"]
        if assignee and "CALIFORNIA" in assignee:
            california_variants[assignee] += 1

    citation_profile = {
        "rows_scanned": 0,
        "citation_json_rows": 0,
        "citation_json_failures": [],
        "edges_all": 0,
        "edges_after_excluding_univ_california": 0,
        "distinct_citing_patents": 0,
        "distinct_cited_uc_pubs": 0,
        "distinct_citing_assignees": 0,
        "sample_edges_after_exclusion": [],
    }
    q3_pairs = set()
    q3_pairs_citing_patent_subclass = set()
    citing_patents = set()
    cited_uc = set()
    citing_assignees = set()
    conn = sqlite3.connect(SQLITE_PATH)
    conn.row_factory = sqlite3.Row
    for row in conn.execute("select Patents_info, cpc, citation from publicationinfo"):
        citation_profile["rows_scanned"] += 1
        assignee, pub, _app, _country = parse_info(row["Patents_info"])
        try:
            citations = json.loads(row["citation"] or "[]")
            citation_profile["citation_json_rows"] += 1
            profile["citation_entries"] += len(citations)
        except Exception as exc:
            citations = []
            if len(citation_profile["citation_json_failures"]) < 5:
                citation_profile["citation_json_failures"].append(str(exc))
        citing_level5 = None
        for citation in citations:
            cited_pub = citation.get("publication_number") if isinstance(citation, dict) else None
            if cited_pub not in uc_pubs:
                continue
            citation_profile["edges_all"] += 1
            if assignee == "UNIV CALIFORNIA":
                continue
            citation_profile["edges_after_excluding_univ_california"] += 1
            if len(citation_profile["sample_edges_after_exclusion"]) < 12:
                citation_profile["sample_edges_after_exclusion"].append(
                    {"citing_pub": pub, "citing_assignee": assignee, "cited_pub": cited_pub}
                )
            citing_patents.add(pub)
            cited_uc.add(cited_pub)
            citing_assignees.add(assignee)
            for group in by_pub[cited_pub]["level5"]:
                q3_pairs.add((assignee, titles[group], group))
            if citing_level5 is None:
                try:
                    citing_cpc = json.loads(row["cpc"] or "[]")
                except Exception:
                    citing_cpc = []
                citing_level5 = primary_groups(citing_cpc, 5, ancestor_at_level)
            for group in citing_level5:
                q3_pairs_citing_patent_subclass.add((assignee, titles[group], group))
    conn.close()
